package test;

import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.swt.widgets.Shell;

public class TestClass {
    ICompilationUnit cu;
    Shell shell;
    boolean editorExists = true;

    public void testMethod() {
        ElementValidator.check(cu, shell, ActionMessages.FormatElementAction_label, editorExists);
    }

    // Dummy classes for compilation
    static class ElementValidator {
        public static boolean check(Object o1, Object o2, String s, boolean b) { return true; }
    }
    static class ActionMessages {
        public static String FormatElementAction_label = "Old Label";
    }
    static class JavaEditorMessages {
        public static String JavaEditor_FormatElementDialog_label = "New Label";
    }
}

